def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.22
        if hp <= 3 or no_water >= 1:
            base = DAILY_SALARY * 0.45
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0.0))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    scarcity = 1.0 - supply_ratio

    if hp <= 2 or no_water >= 2:
        emergency = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        return float(max(0.0, min(budget, emergency)))

    if hp <= 4 or no_water >= 1:
        urgent = max(DAILY_SALARY * 0.72, avg_prev + 1.5, highest_prev * 0.78)
        if scarcity > 0.6:
            urgent = max(urgent, highest_prev + 1.0)
        return float(max(0.0, min(budget, urgent)))

    base = DAILY_SALARY * (0.22 + 0.28 * scarcity)

    if highest_prev >= DAILY_SALARY * 1.5:
        base = min(base, DAILY_SALARY * 0.26)
    elif highest_prev >= DAILY_SALARY * 0.95:
        base = min(base, DAILY_SALARY * 0.32)
    elif highest_prev > 0:
        target = highest_prev + 1.25
        cap = DAILY_SALARY * (0.48 + 0.18 * scarcity)
        base = max(base, min(target, cap))

    if desperate_count >= 2:
        base += DAILY_SALARY * 0.08
    if rich_count >= 2 and scarcity > 0.5:
        base += DAILY_SALARY * 0.06
    if day >= 8:
        base += DAILY_SALARY * 0.05

    safe_cap = budget
    if day <= 3:
        safe_cap = min(safe_cap, DAILY_SALARY * 0.75)
    elif day <= 6:
        safe_cap = min(safe_cap, DAILY_SALARY * 0.95)

    bid = min(base, safe_cap)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    # If no opponents, bid conservatively.
    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer pressure.
    prev_bids = []
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    lowest_prev_bid = min(prev_bids) if prev_bids else 0.0

    # Base bid depends on supply: when supply is near WATER_REQ, competition is tighter.
    # supply_ratio in [~1.15..~1.92] for given ranges.
    supply_ratio = supply / float(WATER_REQ)
    tightness = 1.0
    if supply_ratio <= 1.2:
        tightness = 1.25
    elif supply_ratio <= 1.35:
        tightness = 1.15
    elif supply_ratio <= 1.6:
        tightness = 1.05
    else:
        tightness = 0.95

    # My urgency: if I have gone without water multiple days or low HP, increase.
    urgency = 1.0
    if hp <= 2.0:
        urgency = 1.35
    elif hp <= 4.0:
        urgency = 1.2
    if no_water_days >= 2:
        urgency *= 1.15

    # Opponent pressure: if someone bid very high yesterday, we don't match fully, but we must not underbid.
    # Use thresholds relative to DAILY_SALARY.
    pressure = 1.0
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        pressure = 1.25
    elif highest_prev_bid >= DAILY_SALARY * 0.5:
        pressure = 1.12
    elif lowest_prev_bid <= DAILY_SALARY * 0.2:
        pressure = 1.05

    # Strategy: aim for a mid-high bid that beats the likely low bidders but avoids the extreme high bids.
    # Anchor around 0.55*salary, adjusted by tightness/urgency/pressure.
    target = DAILY_SALARY * 0.55 * tightness * pressure * urgency

    # Additional adjustment by day: later days can require more water to avoid running out.
    if int(day) >= 7:
        target *= 1.08

    # Ensure we don't bid more than budget and keep non-negative.
    bid = max(0.0, min(budget, target))

    # If budget is too low, still bid something to try to secure water.
    if bid < 1.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.15)

    return float(bid)
